rtoire analysis", "children": [{"id": "4573a01d-5e58-46c8-8db9-cb418584f3d3", "type": "concept", "title": "chorale excerpts"}, {"id": "2dba0bc2-2ec7-492f-8b46-ad2d708f2ab9", "type": "concept", "title": "piano miniatures"}, {"id": "cac42be5-e788-42c2-be54-bf33fbb9c845", "type": "concept", "title": "song progressions"}], "description": "Students analyze short examples from classical, popular, jazz-adjacent, and media music."}, {"id": "de39bda6-5918-477e-961f-3b6ec8ed9e9f", "type": "subtopic", "title": "Creative writing", "children": [{"id": "850b2253-ab78-45ee-9f50-f484f0fb4696", "type": "concept", "title": "four-part chorale phrase"}, {"id": "5a0ebc84-be22-4778-908f-d8596dbb6e74", "type": "concept", "title": "sequence composition"}, {"id": "e769461b-cefb-41e4-9b7a-6d0e1e2cd0ea", "type": "concept", "title": "melody with NCTs"}], "description": "Students compose short progressions or phrases using course vocabulary."}, {"id": "e30a871a-123b-4662-97f2-9399098ede55", "type": "subtopic", "title": "Cross-genre translation", "children": [{"id": "475a5af5-9b23-4de0-b95b-15aca6f92275", "type": "concept", "title": "lead-sheet bridge"}, {"id": "fae47ad9-0c3f-4fd8-ae4e-d351105dd183", "type": "concept", "title": "functional loops"}, {"id": "aed4d5af-1874-4fdc-8ffb-02c801bd03d2", "type": "concept", "title": "harmonic reduction"}], "description": "The class connects Roman numerals, figured bass, and chord symbols."}]}], "dbBacked": true}$mt2json$::jsonb,
