set
  title = 'Music Theory II',
  goal = 'Music Theory II',
  summary = 'A second-semester college music theory course focused on diatonic harmony, voice leading, and tonal syntax. Students write and analyze four-part textures, dominant seventh chords, non-chord tones, phrase structures, cadences, harmonic progressions, figured bass, and introductory two-part counterpoint while connecting written work to listening, keyboard realization, repertoire, and creative application.',
  data = $mt2json${"slug": "music-theory-ii", "title": "Music Theory II", "description": "A second-semester college music theory course focused on diatonic harmony, voice leading, and tonal syntax. Students write and analyze four-part textures, dominant seventh chords, non-chord tones, phrase structures, cadences, harmonic progressions, figured bass, and introductory two-part counterpoint while connecting written work to listening, keyboard realization, repertoire, and creative application.", "topics": [{"id": "5eca6b16-d95c-4539-8336-42e3f0adc8d1", "type": "topic", "title": "Voice-Leading Principles", "description": "Voice leading is the craft of moving individual musical lines so harmony sounds clear, singable, and stylistically convincing.", "children": [{"id": "5e0cab4a-b5bf-492d-81ff-98edef68716d", "type": "subtopic", "title": "Line independence", "children": [{"id": "28c88e42-0eed-471f-819f-528cf9bcec5c", "type": "concept", "title": "contrary motion"}, {"id": "836815a9-a3a8-41ff-bea7-ba1c29e93dc7", "type": "concept", "title": "oblique motion"}, {"id": "8a6b42c4-f0ef-4748-8eae-e8d4c811b623", "type": "concept", "title": "common-tone retention"}], "description": "Students learn to hear and write each voice as a real melodic strand."}, {"id": "bd9ba86b-71ad-4b9c-b54a-61368066885b", "type": "subtopic", "title": "Spacing, range, and doubling", "children": [{"id": "66b7bae3-9a12-4bbe-8e2f-5b356e9b5ae3", "type": "concept", "title": "voice ranges"}, {"id": "7c3ab287-bf79-4dc2-bbaf-cdde96ee94cd", "type": "concept", "title": "open and close spacing"}, {"id": "498758a4-b74e-4a8e-a74c-3316f974a1b3", "type": "concept", "title": "doubling choices"}], "description": "The class establishes practical SATB norms that prevent muddy or unperformable textures."}, {"id": "40da6e17-5bdb-40cc-82f0-59c3558c87e8", "type": "subtopic", "title": "Avoiding part-writing errors", "children": [{"id": "8a849e28-d02b-471c-a556-5541d0a0b81e", "type": "concept", "title": "parallel fifths"}, {"id":